// turn.rs:474 — 每次 turn 开始前检查
let total_usage_tokens = sess.get_total_token_usage().await;
// → 148_000

let auto_compact_limit = turn_context
  .model_info
  .auto_compact_token_limit()
  .unwrap_or(i64::MAX);
// → 120_000

if total_usage_tokens >= auto_compact_limit {
  // 触发预压缩
}

// compact.rs — run_pre_sampling_compact()
// → run_auto_compact(
//     sess, turn_context,
//     InitialContextInjection::DoNotInject,
//     CompactionReason::ContextLimit,
//     CompactionPhase::PreTurn,
//   )
// → run_compact_task_inner_impl()

// 步骤1: 调模型生成摘要
// drain_to_completed() — 发送完整历史给模型
// 模型输出:
SUMMARY_PREFIX + "已完成：读取 auth.rs，分析依赖图\n待完成：重写核心函数"

// 步骤2: 收集用户消息
collect_user_messages(history_items)
// 从所有 ResponseItem::Message { role: "user" } 中
// 筛选非摘要消息（!is_summary_message()）
// 返回: [
//   "帮我重构认证模块",
//   "继续分析依赖关系",
// ]

// 步骤3: 重建历史（最多保留 20K tokens 用户消息）
build_compacted_history(
  initial_context: vec![],  // DoNotInject → 空
  user_messages: &["帮我重构认证模块", "继续分析依赖关系"],
  summary_text: "SUMMARY_PREFIX\n已完成：...",
)
// COMPACT_USER_MESSAGE_MAX_TOKENS = 20_000

// 步骤4: 原子替换历史
sess.replace_compacted_history(
  new_history,          // 压缩后的历史
  reference_context_item: None,  // DoNotInject → None
  compacted_item: CompactedItem {
    message: summary_text,
    replacement_history: Some(new_history),
  },
).await;

// 重置 WebSocket session
client_session.reset_websocket_session();

// 重新计算 token 使用
sess.recompute_token_usage(&turn_context).await;
// total_tokens: 148K → 32K ✓

// turn.rs:492 — SSE 流处理完成后
let total_usage_tokens = sess.get_total_token_usage().await;
// → 195_000（多次工具调用后）
let token_limit_reached = total_usage_tokens >= auto_compact_limit;
// → true
let needs_follow_up = model_needs_follow_up || has_pending_input;
// → true（模型发起了工具调用）

if token_limit_reached && needs_follow_up {
  run_auto_compact(
    &sess, &turn_context,
    InitialContextInjection::BeforeLastUserMessage,  // ← 轮中专用
    CompactionReason::ContextLimit,
    CompactionPhase::MidTurn,
  ).await;
  client_session.reset_websocket_session();
  continue;  // ← 重新进入外层循环
}

// compact.rs — InitialContextInjection::BeforeLastUserMessage
// insert_initial_context_before_last_real_user_or_summary()
//
// 压缩后历史插入顺序:
// 1. [user] 继续重写 handler.rs  ← 最后真实用户消息之前
// 2. [初始 context 注入]          ← 插入点
// 3. [user] 再跑一次测试          ← 最后真实用户消息
// 4. [user] 压缩摘要...
//
// reference_context_item = Some(turn_context.to_turn_context_item())
// → 下一轮 turn 不再重注入（已嵌入历史中）

total_tokens: 195K → 45K ✓

// 用户手动执行 /compact
// compact.rs — run_compact_task()

let start_event = EventMsg::TurnStarted(TurnStartedEvent {
  turn_id: turn_context.sub_id.clone(),
  ..
});
sess.send_event(&turn_context, start_event).await;

// 调用 run_compact_task_inner() 时参数:
// CompactionTrigger::Manual
// CompactionPhase::StandaloneTurn
// InitialContextInjection::DoNotInject

// 完成后发送警告:
let warning = EventMsg::Warning(WarningEvent {
  message: "Heads up: Long threads and multiple \
    compactions can cause the model to be less \
    accurate...",
});
sess.send_event(&turn_context, warning).await;

total_tokens: 88K → 18K ✓
